<template><div class="container-page py-10"><p class="text-sm font-semibold text-primary-700">Admin</p><h1 class="mt-2 text-3xl">Property Media</h1><p class="mt-2 text-neutral-600">Select a property to manage its images and marketing videos.</p><div class="card mt-7 p-6"><label class="label" for="media-property">Property</label><select id="media-property" v-model="propertyId" class="input"><option value="">Choose a property</option><option v-for="property in properties" :key="property.id" :value="property.id">{{property.name}}</option></select></div><AdminPropertyMediaManager v-if="selected" :key="selected.id" :property-id="selected.id" :property-name="selected.name"/></div></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin-auth'});const db=useSupabase(),propertyId=ref('');const{data:properties}=useAsyncData('admin-media-properties',async()=>{const{data,error}=await db.from('properties').select('id,name').order('name');if(error)throw error;return data||[]});const selected=computed(()=>properties.value?.find(property=>property.id===propertyId.value));useSeoMeta({title:'Property Media | Lexshield Admin',robots:'noindex,nofollow'})</script>
